check_hash_for_unencrypted_protocol(hash) {
    walk(hash.value, [_, val])
    val.ir_type == "String"
    lower(val.value) == "http"
    not contains(lower(val.value), "https")
}

check_hash_for_encryption_disabled(hash) {
    some path, val
    walk(hash.value, [path, val])
    val.ir_type == "Boolean"
    val.value == true
    count(path) > 0
    lower(path[count(path)-1]) == encryption_disabled_names[_]
}

